local root=assert(os.getenv('QCOM_VP_PROBE_ROOT'))..'/'
platform={moduletype='Container',qemu_inst_mgr={moduletype='QemuInstanceManager'},
    apss_instance={moduletype='QemuInstance',args={'&qemu_inst_mgr','AARCH64'},accel='tcg',
        sync_policy='multithread-quantum',qemu_args='-d in_asm -D '..root..'producer.log'},
    apss_router={moduletype='router'},
    apss_access={moduletype='AccessMonitor',initiator_socket={bind='&apss_router.target_socket'}},
    apss={moduletype='cpu_arm_cortexA53',args={'&apss_instance'},rvbar=0x300000,
        has_el3=true,has_el2=true,mem={bind='&apss_access.target_socket'}},
    rom={moduletype='gs_memory',read_only=true,
        target_socket={address=0x300000,size=0x1000,bind='&apss_router.initiator_socket'},
        load={{bin_file=root..'producer.bin',offset=0}}},
    fuses={moduletype='qcom,sm8850-fuse-controller',lifecycle=5,
        calibration_fuses=root..'calibration.bin',
        jtag_id=0x002b30e1,oem_hw_id=0x51,oem_product_id=0,
        chip_id=0x01234567,serial_number=0x89abcdef,tme_debug_vector0=0x800,tme_debug_vector1=0,
        pte_row4_msb=0xa5a50100,
        oem_pk_hash_sha384=string.rep('00',48),
        secondary_hw_key_programmed=true,
        oem_config6=0,mrc0=0,
        qfprom_write_permissions_lsw=0x1800c060,qfprom_write_permissions_msw=0,
        qfprom_read_permissions_lsw=0x10000000,qfprom_read_permissions_msw=0,
        fuse_redundancy_enable0=0x08000000,fuse_redundancy_enable1=0,
        feature_config9=0,feature_config11=0,feature_config18=0,feature_config19=0,
        qc_config0=0,qc_config1=0,qc_config4=0,qc_config5=0,qc_config6=0,qc_config7=0,
        oem_config0=0,oem_config2=0,oem_config5=0x0f,oem_security_policy_lsb=0x810,
        antirollback0=0,antirollback17=0,antirollback18=0,antirollback22=0,antirollback23=0,
        patch_version=0,boot_config=0,secure_boot=0,captured_boot_gpio=0,
        test_image_vector1=0,fec_error_status=1,rom_error_status=0,
        corrected_policy_socket={address=0x02302090,size=0x18,bind='&apss_router.initiator_socket'},
        pte_identity_socket={address=0x221c20ec,size=4,bind='&apss_router.initiator_socket'},
        target_socket={address=0x221c8000,size=0x2000,bind='&apss_router.initiator_socket'}}}
